        str_n = str(abs(n))
        first_digit = int(str_n[0])
        last_digit = int(str_n[-1])
        return first_digit % 2 == 1 and last_digit % 2 == 1

    count = 0
    for num in nums:
        if num > 10 and isFirstLastDigitOdd(num):
            count += 1
    return count

